{
  "findings": [
    {
      "ref": "D501",
      "area": "age_gating",
      "claim": "The app is intended for children ages 2–8.",
      "stance": "neutral",
      "quote": "Packed with fun, standards-aligned reading games, math games, phonics lessons, and interactive storybooks, the app has helped over 21 million preschool and elementary students learn at home, at school, and on the go. Join Kodi the Bear and friends on exciting educational adventures that spark curiosity, build confidence, and inspire a lifelong love of learning."
    },
    {
      "ref": "D501",
      "area": "content",
      "claim": "The app includes characters Ollo the Elephant, Reya the Red Panda, Peck the Hummingbird, and Sandy the Dingo.",
      "stance": "neutral",
      "quote": "From ABC games and phonics practice to counting, addition, and shapes, kids can explore over 5,000 educational games and activities with Kodi’s friends: • Ollo the Elephant – phonics and letter sounds • Reya the Red Panda – storytime and writing • Peck the Hummingbird – numbers and counting • Sandy the Dingo – puzzles, memory, and problem-solving"
    },
    {
      "ref": "D501",
      "area": "data",
      "claim": "The app is COPPA-compliant and collects no personally identifiable information.",
      "stance": "mitigation",
      "quote": "Created in partnership with the Stanford Graduate School of Education by education experts, aligned with Head Start and Common Core Standards, COPPA-compliant, and 100% free—no ads, no subscriptions."
    },
    {
      "ref": "D501",
      "area": "money",
      "claim": "The app has no in-app purchases, loot boxes, pay-to-win mechanics, or subscriptions.",
      "stance": "mitigation",
      "quote": "Khan Academy Kids is 100% free with no ads or subscriptions."
    },
    {
      "ref": "D502",
      "area": "screen_time",
      "claim": "A parent reports concern about screen time and wants to limit it to occasional use.",
      "stance": "risk",
      "quote": "We are very strict with screen time (basically no screens at all, except for a family movie night once or twice per month where I'll put something on the projector)."
    },
    {
      "ref": "D503",
      "area": "screen_time",
      "claim": "A parent reports that their child uses Khan Academy Kids as a calm activity but still prefers non-screen tasks.",
      "stance": "neutral",
      "quote": "My 4yo likes to play khan academy kids, but it's just a fun screen activity when we need the kids to be calm."
    },
    {
      "ref": "D504",
      "area": "money",
      "claim": "A reviewer states the app is free and includes no adverts.",
      "stance": "mitigation",
      "quote": "It is free. It includes learning games that give rewards in the game like musical instruments, or clothes to play dress up on one of the characters, or (my son's favourite) bugs to add to a bug house. It also includes drawing/colouring in. There are no adverts either."
    },
    {
      "ref": "D505",
      "area": "age_gating",
      "claim": "The app is designed for children ages two to seven.",
      "stance": "neutral",
      "quote": "Khan Academy Kids is an award-winning educational app for young learners ages two to seven."
    },
    {
      "ref": "D506",
      "area": "content",
      "claim": "A parent reports that their child has learned letter recognition, colors, counting to ten, and basic concepts from the app.",
      "stance": "neutral",
      "quote": "She loves it, but I have no frame of reference for how she's learning from it. ... She has letter recognition, understands under/over etc. Can count to ten, knows her colors."
    },
    {
      "ref": "D506",
      "area": "data",
      "claim": "A reviewer notes that parents report getting ideas for teaching from the app.",
      "stance": "neutral",
      "quote": "What is interesting about the study is that parents report getting ideas for teaching from the app - so maybe a dial effect (on parent and child)."
    },
    {
      "ref": "D507",
      "area": "content",
      "claim": "A reviewer mentions that the app includes read-aloud storybooks in English and Spanish.",
      "stance": "neutral",
      "quote": "Choose “Read To Me” for read-aloud storybooks in English or Spanish."
    },
    {
      "ref": "D508",
      "area": "developer_record",
      "claim": "A reviewer states that turning a school into an academy made no difference to anything and is now run like a business.",
      "stance": "risk",
      "quote": "It is NOW run like a business and not a school. If the school is joining a larger academy (a Multi Academy Trust) you will probably notice nothing at all other than a marked increase in corporate behaviour and language in communications."
    }
  ]
}
